  else p.ok(msg.result);
};

async function prepareStorage(bytes) {
  const { storage } = navigator;
  const { quota, usage } = await storage.estimate();
  if (quota - usage < bytes * 1.2) return 'no-space';
  const kept = (await storage.persisted())
    || (await storage.persist());
  return kept ? 'persistent' : 'best-effort';
}

await prepareStorage(300e6); // a 300 MB model

// vectors: Float32Array, n rows of dim, unit length
function search(vectors, dim, query, k = 5) {
  const scores = [];
  for (let row = 0; row * dim < vectors.length; row++) {
    let score = 0;
    for (let i = 0; i < dim; i++) {
      score += vectors[row * dim + i] * query[i];
    }
    scores.push({ row, score });
  }
  return scores.sort((a, b) => b.score - a.score)
    .slice(0, k);
}
